import csv
with open('outputs/t10_accessibility_scores.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    print('Header:', header)
    print('Number of columns in header:', len(header))
    for i, row in enumerate(reader):
        if len(row) != len(header):
            print(f'Row {i+1} has {len(row)} columns, expected {len(header)}')
        else:
            print(f'Row {i+1}: OK ({len(row)} columns)')
