import csv

# Read stop data from t06
stop_data = {}
with open('outputs/t06_stop_service_intensity.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_data[row['stop_id']] = (int(row['n_departures']), int(row['n_routes']))

# Read from t09 to get nearest_stop_id for each qid
t09_data = {}
with open('outputs/t09_poi_nearest_stop.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        t09_data[row['qid']] = row['nearest_stop_id']

# Read from t10 and compare
with open('outputs/t10_accessibility_scores.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        qid = row['qid']
        nearest_stop_id = t09_data[qid]
        t10_departures = int(row['n_departures'])
        t10_routes = int(row['n_routes'])

        if nearest_stop_id in stop_data:
            expected_departures, expected_routes = stop_data[nearest_stop_id]
            if t10_departures != expected_departures:
                print(f'Departures mismatch for {qid}: expected={expected_departures}, got={t10_departures}')
            if t10_routes != expected_routes:
                print(f'Routes mismatch for {qid}: expected={expected_routes}, got={t10_routes}')
        else:
            print(f'Stop {nearest_stop_id} not found in t06 for qid {qid}')

print('Departures/routes check complete')
""}
